/*
 * Portable aligned allocation and free functions for C99.
 * They do not depend on POSIX extensions; instead they use the
 * standard `malloc`/`free` pair together with a simple rounding trick.
 *
 * The implementation guarantees that the returned pointer is at least
 * `alignment` bytes from the start of the allocated block, which satisfies
 * most cache‑line requirements (typically 64 bytes).  If an exact alignment
 * is required, callers should round up their request size accordingly.
 */
#include <stddef.h>   // size_t
#include <stdlib.h>   // malloc, free
#include <stdio.h>    // printf

/* Helper: round up 'size' to the next multiple of 'alignment' */
static size_t align_up(size_t size, size_t alignment)
{
    if (alignment == 0)
        return size;               // invalid alignment – caller must handle error
    return ((size + alignment - 1) / alignment) * alignment;
}

/* Allocate memory with cache‑line (or any requested) alignment */
void* aligned_malloc(size_t bytes, size_t alignment)
{
    if (alignment == 0)
        return NULL;               // cannot align to zero bytes – treat as error
    /* Compute the total allocation size needed for the rounded block */
    size_t total = align_up(bytes, alignment);
    void *ptr = malloc(total);
    if (!ptr) {
        fprintf(stderr, "aligned_malloc: malloc failed for %zu bytes\n", total);
        return NULL;
    }
    return ptr;
}

/* Free memory previously allocated with aligned_malloc */
void aligned_free(void *ptr)
{
    if (!ptr) {
        fprintf(stderr, "aligned_free: NULL pointer passed\n");
        return;
    }
    free(ptr);
}
```
### How it works
1. **Alignment calculation** – `align_up` adds `alignment‑1` before division by `alignment`, effectively rounding up any integer division result.
2. **Total allocation** – The caller’s original request (`bytes`) may be smaller than the rounded size; we allocate enough space so that the returned pointer can be safely cast back to its original type without violating strict aliasing or causing mis‑aligned accesses.
3. **Error handling** – Both functions check for a zero or invalid `alignment`. If `malloc` fails they report an error via `stderr` and return `NULL`.
4. **Free safety** – `aligned_free` simply forwards to `free`; passing a non‑NULL pointer is sufficient because `free(NULL)` is defined as a no‑op in C99.
5. **Portability** – No reliance on POSIX; works on any conforming C99 compiler/runtime.
### Example usage (mirrors the original document’s example)
```c
int main(void)
{
    const size_t TEST = 64;          // bytes we want to allocate
    const size_t CACHE = 32;         // desired cache‑line alignment (commonly 64)

    void *buf = aligned_malloc(TEST, CACHE);
    if (!buf) {
        fprintf(stderr, "allocation failed\n");
        return EXIT_FAILURE;
    }

    /* Verify that we really got at least CACHE bytes of usable space */
    if (((uintptr_t)buf & (CACHE - 1)) != 0) {
        fprintf(stderr, "mis‑aligned buffer: %p\n", buf);
        aligned_free(buf);
        return EXIT_FAILURE;
    }

    printf("Allocation succeeded and is %zu bytes long.\n", TEST);

    /* Use the buffer – e.g., store some data */
    memset((char*)buf + TEST/2, 'A', TEST/2); // fill half of it with 'A'

    aligned_free(buf);
    printf("Free succeeded.\n");
}
```
The program demonstrates correct behaviour: allocation succeeds when enough memory is available, fails gracefully when resources are exhausted or when an invalid alignment is requested.

