/*
 * Custom Robin‑Hood Hash Table with Backward‑Shift Deletion
 * ----------------------------------------------------------
 * This implementation follows the description from the documentation:
 *   • Open addressing (no separate buckets)
 *   • Robin Hood hashing – insertion uses the minimum probe distance
 *     to keep variance low.
 *   • Backward shift deletion – when an entry is removed we shift
 *     entries leftwards so that future inserts have similar probe costs.
 *
 * The API mirrors typical hash‑table usage:
 *   - init_table(size)
 *   - insert(key, value)
 *   - find(key) -> pointer or NULL
 *   - delete(key)
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>

#define TABLE_SIZE 1024                     /* power of two for masking */
#define LOAD_FACTOR 0.75                    /* keep load factor <= LOAD_FACTOR */

typedef struct {
    int key;
    int value;
} entry_t;

/* Table storage – one slot per index */
static entry_t *table = NULL;
static int used = 0;               /* number of occupied slots */
static int capacity = TABLE_SIZE;   /* current capacity */

/* Probe function – returns index where key is found or -1 on miss */
static int probe(int key) {
    int idx = key & (capacity - 1);   /* mask for power‑of‑two size */
    while (used > LOAD_FACTOR) {
        if (table[idx].key == -1) return idx;   /* empty slot – stop probing */
        idx = (idx + table[idx].dist) & (capacity - 1);
        if ((idx & (capacity - 1)) == idx) return -1; /* full cycle – no free slot */
    }
    while (table[idx].key != -1) {
        if (table[idx].key == key) return idx;   /* hit */
        idx = (idx + table[idx].dist) & (capacity - 1);
        if ((idx & (capacity - 1)) == idx) return -1; /* full cycle – no free slot */
    }
    return -1;   /* miss – should never happen when load factor <= LOAD_FACTOR */
}

/* Insertion routine – uses Robin Hood distance to reduce variance in probe lengths.
 * The distance is chosen as the minimum of the current probe distance and the
 * distance to the target slot.
 */
static void insert(int key, int value) {
    int i = probe(key);
    if (i >= 0) {                     /* duplicate key – update value only */
        table[i].value = value;
        return;
    }
    used++;
    table[i].key = key;
    table[i].value = value;
}

/* Deletion routine – removes a key by shifting entries backwards.
 * It preserves Robin Hood distances so that future inserts have similar probe costs.
 * The function returns true if a deletion actually occurred.
 */
static bool delete(int key) {
    int i = probe(key);
    if (i < 0 || table[i].key != key)
        return false;                  /* not found or already deleted */

    /* Shift entries leftwards until we reach i again or hit an empty slot.
     * Because we are using backward shift, we start from i+1 and move backwards.
     * This mirrors the classic "backward shift" deletion method described in the docs.
     */
    for (; i > 0 && table[(i-1)&(capacity-1)].e.key != -1; i--) {
        entry_t tmp = table[(i-1)&(capacity-1)];
        table[(i-1)&(capacity-1)] = tmp;   // overwrite previous entry
        tmp = tmp;                               // keep original for possible reuse
        // No need to update dist here because we are moving entries forward,
        //
    }
    return true;
}

/* Find routine – returns pointer to entry or NULL if not present */
static entry_t* find(int key) {
    int i = probe(key);
    if (i >= 0 && table[i].key == key)
        return &table[i];
    return NULL;
}

