    printf("Running unit tests for Robin‑Hood hash table...\n");

    // Test initialization with zero capacity should fail gracefully.
    assert(!init_table(0));

    // Test normal insertion and lookup.
    init_table(64);
    insert(42, 99);
    assert(find(42)->value == 99);

    // Insert duplicate values to verify update semantics.
    insert(-7, 33);
    assert(find(-7)->value == 33);

