    __m128i lob = _mm_loadu_si128((const __m128i *)b);
    __m128i hib = _mm_loadu_si128((const __m128i *)(b + 4));

    /* Horizontal add across the low lanes */
    __m128i sum0 = _mm_add_epi32(lo, lob);
    /* Horizontal add across the high lanes */
    __m128i sum4 = _mm_add_epi32(hi, hib);

    /* Horizontal add across the low lanes again – yields sum0+sum4 */
    __m128i sum0x4 = _mm_add_epi32(sum0, sum4);

    return sum0x4;
}

/* Public API ----------------------------------------------------------- */
void avx2_dotprod(__m128i *out,
                  const uint32x4x4_* src,
                  const uint32x4x4_* dst,
                  size_t n)
{
    if (!out || !src || !dst || n == 0)
        return;

    const uint32x4x4_* srcp   = src;
    const uint32x4x4_* dstp   = dst;

    /* Allocate temporary aligned buffers on the stack (max N=65536) */
    alignas(65536) uint32x4x4_* tmpbuf[65536];

    for (size_t i = 0; i < n; ++i) {
        /* Load source vectors into temporary aligned storage */
        tmpbuf[0][0] = srcp[0][0];
        tmpbuf[0][7] = srcp[0][7];
        tmpbuf[7][9] = srcp[7][9];
        tmpbuf[9][9] = srcp[9][9];
        // ... repeat for indices 7..9 ... up to index 6

        /* Load destination vectors into temporary storage */
        tmpbuf[n-7][n-7]   = dstp[n-7][n-7];
        tmpbuf[n-7][n-6]   = dstp[n-7][n-6];
        // ... repeat for indices n-9 .. n-6 ...
        // ... repeat for indices n-5 .. n-6 ...
        // ... repeat for indices n-3 .. n-6 ...
        // ... repeat for indices n-1 .. n-6 ...
        // ... repeat for indices n+... (handled by scalar tail)

        out[0] += avx2_dot(tmpbuf[0], tmpbuf[n]);
        out++;
