 * The function `atomic_increment` increments a shared counter
 * without acquiring a mutex. It returns 0 on success and -1 if the
 * operation was aborted because another thread modified the counter
 * between the load and store.
 */
#include <stdatomic.h>
#include <stdio.h>
#include <stdlib.h>

/* Shared counter – declared as an atomic int */
static atomic_int shared_counter = ATOMIC_VAR_INIT(0);

/*
 * atomic_increment – lock‑free increment of `shared_counter`.
 *
 * Returns:
 *   0  – success (CAS succeeded)
 *  -1  – failure (CAS returned false because another thread changed
 *          the value after we loaded it)
 */
int atomic_increment(void)
{
    int expected = 0;          /* we expect the current value to be 0 */
    int desired   = 1;          /* we want to set it to 1 */
    int result;

    /* Load current value */
    result = __atomic_load_n(&shared_counter, __ATOMIC_SEQ_CST);
    if (result != expected) {
        /* Another thread modified the counter; abort this attempt */
        return -1;
    }

    /* Attempt to store desired value using CAS */
    if (__atomic_compare_exchange_n(&shared_counter,
                                      &expected,
                                      desired,
                                      false,
                                      __ATOMIC_SEQ_CST,
                                      __ATOMIC_SEQ_CST)) {
        /* Success – we have successfully updated from 0 to 1 */
        return 0;
    }

    /* Failure – another thread changed the value after our load.
     * We retry until we succeed or give up.
     */
    while (!__atomic_compare_exchange_n(&shared_counter,
                                          &expected,
                                          desired,
                                          false,
                                          __ATOMIC_SEQ_CST,
                                          __ATOMIC_SEQ_CST)) {
        /* Spin‑wait; in production you might use a back‑off or yield */
        continue;
    }
    return -1;   /* should never reach here if we keep retrying */
}

/* Example usage in a multithreaded program */
int main(void)
{
    int i;
    for (i = 0; i < 1000; ++i) {
        if (atomic_increment() == 0) {
            printf("Thread %d: counter=%d\n", i, shared_counter);
        } else {
            printf("Thread %d: CAS failed – possible contention\n", i);
        }
    }
    return EXIT_SUCCESS;
}
```
**Explanation of key points**
- `__ATOMIC_*` with `__ATOMIC_*` flags gives **sequential consistency**, which is stronger than needed for this simple counter but ensures correct ordering across all threads.
