/*
 * Reverse the order of bits in a 64‑bit unsigned integer.
 * The algorithm uses three parallel masks (0x5555…, 0x3333…, 0x0F0F…)
 * to extract groups of two bits from both high and low halves,
 * then combines them with shifts and XORs.
 *
 * Time complexity: O(1) – only a fixed number of bitwise ops.
 * Space complexity: O(1) – operates directly on the input value.
 */
static inline uint64_t reverse_bits_parallel(uint64_t x)
{
    /* Masks for extracting pairs from high/low halves */
    const uint64_t mask_high = 0x5555555555555555ULL;   // 0101…
    const uint64_t mask_low  = 0x3333333333333333ULL;   // 0011…
    const uint64_t mask_pair = 0x0F0F0F0F0F0F0F0FULL;   // extracts nibbles

    /* Step 1: split into high/low halves */
    uint64_t hi = x & mask_high;
    uint64_t lo = x & mask_low;

    /* Step 2: reverse each half using pairwise swaps */
    hi = (hi >> 1) | (hi << (sizeof(uint64_t)*8 - 1));
    lo = (lo >> 1) | (lo << (sizeof(uint64_t)*8 - 1));

    /* Step 3: combine halves with swapped nibbles */
    hi = ((hi & mask_pair) << 8) | ((hi & ~mask_pair) >> (sizeof(uint64_t)*8 - 8));
    lo = ((lo & mask_pair) << 8) | ((lo & ~mask_pair) >> (sizeof(uint64_t)*8 - 8));

    /* Step 4: swap halves back to original positions */
    hi ^= lo;
    lo ^= hi;

    return lo;
}
