/*
 * ReaderWriterLock – POSIX implementation with writer‑preference.
 * Guarantees that once a writer has acquired the lock no new readers
 * can enter until all current readers have released it.  This prevents
 * writer starvation while still allowing multiple concurrent readers.
 */
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>

/* Data structure for the lock */
typedef struct {
    pthread_mutex_t   mtx;      /* protects all fields */
    pthread_cond_t    rd_cv;    /* readers wait here */
    pthread_cond_t    wr_cv;    /* writers wait here */
    int               nreaders;  /* number of active readers */
    int               nwriters;  /* number of active writers */
} ReaderWriterLock;

/* Initialise the lock – creates both mutex and condition variables */
ReaderWriterLock *rwlock = NULL;
ReaderWriterLock *rwlock_init(void) {
    ReaderWriterLock *rl = calloc(1, sizeof(*rl));
    if (!rl) return NULL;
    if (pthread_mutex_init(&rl->mtx, NULL) != 0) { free(rl); return NULL; }
    if (pthread_cond_init(&rl->rd_cv, NULL) != 0 || pthread_cond_init(&rl->wr_cv, NULL) != 0) {
        pthread_mutex_destroy(&rl->mtx);
        free(rl);
        return NULL;
    }
    rl->nreaders = rl->nwriters = 0;
    return rl;
}

/* Acquire a read lock – blocks until no writer holds the lock */
int rwlock_rdlock(ReaderWriterLock *lock) {
    if (!lock) return -1;
    pthread_mutex_lock(&lock->mtx);
    while (lock->nwriters > 0 || lock->nreaders > 0) {
        /* Wait until both counters are zero */
        pthread_cond_wait(&lock->rd_cv, &lock->mtx);
        /* Re‑check after waking up – another thread may have released */
        if (lock->nwriters == 0 && lock->nreaders == 0)
            break; /* success */
        else
            continue; /* loop back to wait */
    }
    lock->nreaders++;
    pthread_mutex_unlock(&lock->mtx);
}

/* Release a read lock – wakes one waiting writer if any exist */
int rwlock_unlock(ReaderWriterLock *lock) {
    if (!lock) return -1;
    pthread_mutex_lock(&lock->mtx);
    if (--lock->nreaders == 0)
        pthread_cond_signal(&lock->wr_cv);   /* wake one waiting writer */

    /* Wake any blocked readers/writers (optional but common in practice) */
    pthread_cond_broadcast(&lock->rd_cv);

    pthread_mutex_unlock(&lock->mtx);
}

