static void segv_handler(int sig, siginfo_t *si, void *ctx)
{
    (void)ctx;               // unused in this simple example
    printf("SIGSEGV at %p\n", si->si_addr);
    /* Jump back to the point where we called siglongjmp */
    siglongjmp(env, 1);
