    memset(&sa, 0, sizeof(sa));
    sa.sa_sigaction = segv_handler;
    sa.sa_flags = SA_SIGINFO | SA_RESTART;   // SA_RESTART not needed here

    if (sigaction(SIGSEGV, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Install the handler for SIGBUS as well – it shares the same handler */
    sa.sa_flags |= SA_SIGINFO;   // reuse same handler for both signals
    if (sigaction(SIGBUS, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
