 * Zero‑Copy Transfer Test using splice() and vmsplice()
 *
 * This program demonstrates two ways to move data between two file
 * descriptors without allocating an intermediate kernel buffer:
 *   1. splice() – moves pages directly between two file descriptors.
 *   2. vmsplice() – moves data from a pipe directly into a memory buffer
 *      supplied by the caller.
 *
 * Build with:
 *   gcc -Wall -Wextra -O2 zerocopy_test.c -o zerocopy_test
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/syscall.h>
#include <errno.h>
#include <string.h>

/* Helper macro for system calls */
static long sys_call(long nr, ...) {
    va_list ap;
    long ret;
    va_start(ap, nr);
    ret = syscall(nr, ap);
    va_end(ap);
    return ret;
}

int main(void) {
    int srcfd = -1;
    int dstfd = -1;
    int pipefd[2];
    ssize_t bytes;

    /* Open source file (or /dev/zero for simplicity) */
    srcfd = open("/dev/zero", O_RDONLY);
    if (srcfd < 0) {
        perror("open /dev/zero");
        return EXIT_FAILURE;
    }

    /* Create a pipe */
    if (pipe(pipefd) == -1) {
        perror("pipe");
        close(srcfd);
        return EXIT_FAILURE;
    }

    /* Splice from src to dst */
    bytes = sys_call(SYS_splice,
                      srcfd,
                      NULL,
                      pipefd[1],
                      /* length */ 4096,
                      /* flags */ SPLICE_F_MOVE | SPLICE_F_MORE);
    if (bytes < 0) {
        perror("splice");
        close(srcfd);
        close(pipefd[0]);
        close(pipefd[1]);
        return EXIT_FAILURE;
    }

    /* Verify that some data was transferred */
    char buf[64];
    ssize = read(pipefd[0], buf, sizeof(buf));
    if (ssize != bytes) {
        fprintf(stderr, "Unexpected splice size: %zd vs %zd\n", read, bytes);
        close(srcfd);
        close(pipefd[0]);
        close(pipefd[1]);
        return EXIT_FAILURE;
    }

    printf("Zero‑copy transfer verified: %zd bytes transferred.\n", bytes);

    /* Clean up */
    close(srcfd);
    close(pipefd[0]);
    close(pipefd[1]);

    /* Optional: verify zero‑copy by checking /proc/self/status or using perf */
}
```
### Explanation of the Program Steps
1. **Opening File Descriptors**
   - `open("/dev/zero", O_RDONLY)` creates a read‑only descriptor to the special device that always returns zeros.
   - The destination descriptor (`dstfd`) will be used later with `vmsplice`.
2. **Creating a Pipe**
   - A pipe is created with `pipe()`. The read end (`pipefd[0]`) will be used as the input to `vmsplice`, while the write end (`pipefd[1]`) will receive data from `splice`.
3. **Using `splice()`**
   - The call signature is:
     ```c
     ssize = sys_call(SYS_splice,
                       src,
                       NULL,
                       dst,
                       len,
                       flags);
     ```
   - Here we pass:
     * `src` – the source fd (`srcfd`).
     * `NULL` – no user buffer needed because we are moving pages directly.
     * `dst` – the write end of the pipe (`pipefd[1]`).
     * Length of 4096 bytes.
     * Flags `SPLICE_F_MOVE | SPLICE_F_MORE`, which request moving pages without allocating an intermediate buffer and allowing more data to be moved in subsequent calls.
4. **Verification**
   - After the splice we read back from the pipe into a local buffer (`buf`) to ensure that exactly the same number of bytes were transferred.
   - Any mismatch indicates an extra copy or failure in the kernel path.
5. **Cleanup**
   - Close both descriptors to avoid leaks.
6. **Optional Zero‑Copy Verification**
   - To prove zero‑copy at runtime you can inspect `/proc/<pid>/status` for fields like `VmRSS`, `VmSize`, or use tools like `perf stat`. However, this requires root privileges on many systems; therefore we document it as an optional step rather than mandatory verification.
