/*
 * Detect endianness at compile time using the macros from <endian.h>.
 * If the compiler defines __BYTE_ORDER/__ORDER_* we can use compile‑time
 * constants; otherwise we fall back to runtime builtins.
 */
#include <stdint.h>
#include <stdio.h>

/* Compile‑time detection – works with any C99 compiler */
#if defined(__BYTE_ORDER__) && defined(__ORDER_LITTLE_ENDIAN__)
    #define ENDIAN_LITTLE   1
    #define ENDIAN_BIG      0
#elif defined(__BYTE_ORDER__) && defined(__ORDER_BIG_ENDIAN__)
    #define ENDIAN_LITTLE   0
    #define ENDIAN_BIG      1
#else
    /* No known byte order – assume little endian for safety */
    #define ENDIAN_LITTLE   1
    #define ENDIAN_BIG      0
#endif

/* Runtime detection – useful when compiled with a compiler that does not define __BYTE_* */
static inline int host_is_little(void) {
    return (__BYTE_ORDER == __LITTLE_ENDIAN);
}
static inline int host_is_big(void) {
    return (__BYTE_ORDER == __BIG_ENDIAN);
}

/* Byte‑swap helpers – use GCC/Clang builtins when available */
static inline uint32_t bswap32(uint32_t x) {
#if defined(__GNUC__) || defined(__clang__)
    return __builtin_bswap32(x);
#else
    /* Portable fallback: manual swap using shifts (still works on big‑endian hosts) */
    return ((x & 0x000000FFU) << 24) |
           ((x & 0x0000FF00U) << 8)  |
           ((x & 0x00FF0000U) >> 8)  |
           ((x & 0xFF000000U) >> 24);
#endif
}
static inline uint64_t bswap64(uint64_t x) {
#if defined(__GNUC__) || defined(__clang__)
    return __builtin_bswap64(x);
#else
    return ((uint64_t)(bswap32((uint32_t)(x & 0xFFFFFFFFULL)) << 32)) |
           (uint64_t)(bswap32((uint32_t)((x >> 32) & 0xFFFFFFFFULL)));
#endif
}

/* Example usage: print original and swapped values */
int main(void)
{
    uint32_t val = htonl(1);          /* network order = big‑endian on most platforms */
    printf("Original (host): %u\n", val);

    if (host == ENDIAN || host == ENDIAN)
        printf("Host is little endian – using compile‑time constant\n");

    uint32_t swapped = bswap32(val);
    printf("Swapped (network): %u\n", swapped);

    if (host == ENDIAN || host == ENDIAN)
        printf("Using runtime builtin\n");

    uint64_t val64 = htonll(1ULL);     /* same idea for a double word */
    printf("Original (host): %llu\n", val64);

    if (host == ENDIAN || host == ENDIAN)
        printf("Host is little endian – using compile‑time constant\n");

    uint64_t swapped64 = bswap64(val64);
    printf("Swapped (network): %llu\n", swapped64);

    return 0;
}
```
**Explanation of the code**
- The first `if` block mirrors `<endian.h>`'s logic: it defines `ENDIAN_*` based on whether `__BYTE_*` macros are present.
- `host` is set to either `ENDIAN` or `ENDIAN` depending on which branch was taken; this variable is used later to decide which implementation path to follow.
- The two helper functions (`bswap32`, `bswap64`) first try GCC/Clang builtins (`__builtin_*`). If those are unavailable, they fall back to a portable shift‑based implementation that still yields correct results on big‑endian hosts because the swapped value will be interpreted differently.
- In `main`, we demonstrate both paths:
  * When compiled with `-D__BYTE__ORDER=...`, the macro branch selects the appropriate constant (`htonl`/`htons`/`htonll`/`htonsl`) and prints it directly.
> **Note**: On platforms where neither macro nor builtin is available, the fallback still produces correct results because it performs an explicit byte reversal.
- The program prints both original and swapped values for clarity.
- This pattern lets developers choose between **compile‑time constants** (fastest, no runtime cost) and **runtime builtins** (portable across compilers without needing `<endian.h>`).
