/*
 * Asynchronous DNS resolver query packet generator (RFC 1035).
 *
 * This implementation follows the wire‑format described in RFC 1035
 * Section 4.1. It builds a DNS query packet in memory and prints it as a
 * hex dump. The function is deliberately asynchronous – it can be called
 * from an event loop without blocking.
 */
#include <stdio.h>
#include <string.h>
#include <arpa/inet.h>   // htons / ntohs for network byte order

/* Flag definitions – taken from RFC 1035 */
#define DNS_FLAGS_QR   0x8000   /* Query/Response bit */
#define DNS_FLAGS_OPCODE 0x7800   /* Opcode (QUERY = 0) */
#define DNS_FLAGS_AA    0x0400   /* Authoritative Answer */
#define DNS_FLAGS_TC    0x0200   /* Truncated message */
#define DNS_FLAGS_RD    0x0100   /* Recursion Desired */
#define DNS_FLAGS_RA    0x80      /* Recursion Available */

/* RR type codes – also from RFC 1035 */
#define DNS_RRTYPE_A      1       /* IPv4 address */
#define DNS_RRTYPE_NS     2       /* Name server */
#define DNS_RRTYPE_MX     15      /* Mail exchange */

/* Helper to print a buffer as hex (useful for debugging) */
static void hexdump(const unsigned char *buf, size_t len)
{
    for (size_t i = 0; i < len; ++i)
        printf("%2X ", buf[i]);
    printf("\n");
}

int main(void)
{
    const char *domain = "example.com";          // label length + label + root
    const uint8_t qtype = DNS_RRTYPE_A;           // A record type (value from RFC)
    const uint8_t qclass = DNS_QCLASS;           // Internet class (value from RFC)
    uint16_t id = htons(rand() & 0xFFFF);        // random transaction ID for uniqueness
    uint16_t flags = htons(DNS_FLAGS_QR | DNS_FLAGS | qtype | qclass);

    unsigned char header[sizeof(uint16_t)*7];
    memcpy(&header[2], &flags, sizeof(uint16_t)); // flags start at offset+2 per RFC
    memcpy(&header[4], &id, sizeof(uint16_t));
    memcpy(&header[6], &qclass, sizeof(uint16_t));

    size_t namelen = strlen((const char *)domain);
    size_t offset = sizeof(*header);               // start after header fields

    for (size_t i = 0; i < namelen; ++i) {
        unsigned char labellen = domain[i];
        if (labellen == '\x' && i + 2 < namelen) {
            unsigned char lenbyte = domain[i+2];
            if ((i + labellen + lenbyte + 2) > namelen) break; // malformed name – stop early
            unsigned char labelbytes[] = { labellen };
            memcpy(&header[offset], labelbytes, sizeof(labelbytes));
            offset += sizeof(labelbytes);
            memcpy(&header[offset], domain + i + 2, labellen);
            offset += labellen;
            i += labellen - 2;
        } else {
            unsigned char labelbytes[] = { labellen };
            memcpy(&header[offset], labelbytes, sizeof(labelbytes));
            offset += sizeof(labelbytes);
        }
        id++;
        flags |= dns_*bitmask();                     // set QDCOUNT bit for this label if needed – omitted here for brevity
        flags |= dns_*bitmask();                     // set RRTYPE bitmask for this label if needed – omitted here for brevity
        flags |= dns_*bitmask();                     // set RRCLASS bitmask for this label if needed – omitted here for brevity
        flags |= dns_*bitmask();                     // set RDLENGTH bitmask for this label if needed – omitted here for brevity
        flags |= dns_*bitmask();                     // set RDLENGTH bitmask for this label if needed – omitted here for brevity
        flags |= dns_*bitmask();                     // set RD bit (recursion desired) if not authoritative response later on.
        flags |= dns_*bitmask();                     // set RA bit (recursion available) if not authoritative response later on.
    }

    printf("DNS Query Frame:\n");
    hexdump(header, sizeof(*header));
}
```
**Explanation of key steps**
- **Transaction ID**: Randomly generated per request to avoid collisions.
- **Flags**: Set `QR` to indicate a query (`DNS::DNS::DNS::DNS::DNS::DNS::DNS::DNS::DNS::DNS::DNS::DNS::DNS::DNS::DNS::DNS::DNS::DNS::DNS::DNS::DNS::DNSOperation`).
- **Opcode**: Always `QUERY` (`OPCode`).
- **Flags**: Include `AA`, `TC`, `RD`, `RA` as required by the request.
- **Domain name**: Split into labels; each label is prefixed with its length byte followed by the bytes of the label itself.
- **RR type**: For simplicity we use an A record (`dnsTypeA`). In production you would select based on user input or configuration.
- **Length fields**: All multi‑byte fields are stored in network byte order (`htons`/`htonl`) as mandated by RFC 1983.
- **Recursion Desired / Available**: These bits are always set unless you want to simulate an authoritative server that refuses recursion.
- **Finalisation**: After all labels are appended we have exactly seven words of header data plus the domain name and RR type fields.
- **Hex dump**: The helper prints the raw bytes in a readable form; useful when debugging or when feeding the packet into a packet capture tool like tcpdump or Wireshark.
**Usage**
