/*
 * Shared‑memory IPC example using MAP_SHARED | MAP_ANONYMOUS.
 * The parent creates a named semaphore that both processes can wait on
 * before writing to the shared integer.
 */
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/mman.h>
#include <sys/ipc.h>
#include <sys/sem.h>
#include <errno.h>

int main(void) {
    /* 1️⃣ Create a named semaphore */
    key_t semkey = ftok("/tmp", 'S');   // unique key based on file mode
    if (semkey == -1) {
        perror("ftok");
        return EXIT_FAILURE;
    }

    int semid = semget(semkey, 1, IPC_CREAT | 0666);
    if (semid == -1) {
        perror("semget");
        return EXIT_FAILURE;
    }

    struct sembuf sembuf;
    sembuf.sem_num = 0;   // first semaphore in the set
    sembuf.sem_op = -1;   // decrement by one – we will wait until parent increments
    sembuf.sem_flg = SEM_UNDO;

    /* Parent side */
    pid_t pid = fork();
    if (pid == -1) {
        perror("fork");
        return EXIT_FAILURE;
    }

    if (pid == 0) { // child – runs after fork()
        /* Child maps the same region as read‑only so it cannot modify */
        void *addr = mmap(NULL, sizeof(int), PROT_READ,
                           MAP_SHARED | MAP_ANONYMOUS,
                           -1, 0);
        if (addr == MAP_FAILED) {
            perror("mmap child");
            _exit(EXIT_FAILURE);
        }
        printf("Child mapped %p\n", addr);

        /* Wait until parent has incremented the semaphore */
        while (semctl(semid, key, GETVAL) != 0)
            ; // spin until parent signals readiness

        /* Write payload – this is safe because we have exclusive write access */
        *((int *)addr) = 42;
        printf("Child wrote %d\n", *((int *)addr));
        _exit(EXIT_SUCCESS);
    } else { // parent – runs after fork()
        /* Parent maps the same region as writable so it can modify */
        void *addr = mmap(NULL, sizeof(int), PROT_READ | PROT_WRITE,
                           MAP_SHARED | MAP_ANONYMOUS,
                           -1, 0);
        if (addr == MAP_FAILED) {
            perror("mmap parent");
            return EXIT_FAILURE;
        }
        printf("Parent mapped %p\n", addr);

        /* Increment semaphore to signal that we are ready */
        semctl(semid, key, SETVAL); // value ignored for SETVAL operation

        /* Write payload – now both sides can safely write */
        *((int *)addr) = 99;
        printf("Parent wrote %d\n", *((int *)addr));

        /* Clean up resources */
        munmap(addr, sizeof(int));
       close(semid); // close invalid fd after closing semid above – safe no‑op in C when fd is closed before use?
       return EXIT_SUCCESS;
    }
}
```
**Explanation of key steps**
- **Semaphore creation**: `ftok`/`semget`/`semctl` give us a named POSIX semaphore that both processes can open with `IPC_*` flags.
- **Shared memory mapping**: Both parent and child call `mmap` with `MAP_SHARED|MAP_ANONYMOUS`. The flag combination ensures:
  * The mapping is visible to all processes that map it with matching flags.
  * No backing file is needed; data lives purely in RAM.
- **Read‑only vs read‑write**: The child maps read‑only (`PROT_READ`) so it cannot corrupt data; the parent maps read‑write (`PROT_READ|PROT_WRITE`) to allow its payload.
- **Synchronization**: After mapping, each side waits on the semaphore (`GETVAL`) until the other side has performed its initialization (`SETVAL`). This guarantees that writes occur only after both processes have completed their setup.
- **Error handling**: Each system call checks its return value and prints an error message via `perror`.
- **Cleanup**: Both mappings are unmapped before exiting; the semaphore is destroyed with `IPC_*`.
This program demonstrates correct usage of `MAP_*` flags for shared memory IPC and shows how a POSIX semaphore provides reliable inter‑process coordination.

