/// A lock‑free stack implemented with Treiber's algorithm.
///
/// * `push` inserts an element at the top.
/// * `pop` removes and returns the top element.
/// * Both operations are atomic and return `Result<T, PopError>` where
///   `PopError` indicates whether the stack was empty.
pub struct TreiberStack<T> {
    /// The head of the stack – points to the most recently pushed node.
    head: AtomicPtr<Node<T>>, // Node contains `next: Option<NonNull<Node<T>>>`
}

struct Node<T> {
    next: Option<NonNull<Node<T>>>,
}

impl<T> TreiberStack<T> {
    /// Creates an empty stack.
    pub fn new() -> Self { Self { head: AtomicPtr::new(std::ptr::null_mut()) } }

    /// Pushes a value onto the stack.
    ///
    /// Returns `Ok(value)` on success or `Err(PopError::Empty)` if the stack is empty.
    pub fn push(&self, value: T) -> Result<(), PopError> {
        // Load current head atomically.
        let mut cur = self.head.load(Ordering::Acquire);
        loop {
            // If head is null we have reached the bottom of the stack – cannot push.
            if cur.is_null() {
                return Err(PopError::Empty);
            }
            // Dereference to get the node pointer (may be null if we are in an ABA window).
