/// A simple node for the Treiber stack.
struct Node {
    next: Option<NonNull<Node>>, // points to the next node or None
}

/// The top of the stack – an `AtomicPtr<Node>` that always points to the most recent node.
pub struct TreiberStack {
    head: AtomicPtr<Node>,
}

impl TreiberStack {
    /// Create an empty stack.
    pub fn new() -> Self { Self { head: AtomicPtr::new(std::ptr::null_mut()) } }

    /// Push a value onto the stack.
    ///
    /// Returns `Ok(value)` on success or `Err(PopError::Empty)` if the stack is empty.
    pub fn push(&self, value: i32) -> Result<(), PopError> {
        // Load current head atomically.
        let mut cur = self.head.load(Ordering::Acquire);
        loop {
            // If head is null we have reached the bottom of the stack – cannot push.
            if cur.is_null() {
                return Err(PopError { empty: true });
            }
            // Dereference to get the node pointer (may be null if we are in an ABA window).
            let node = unsafe { &*cur };
            // Check if this node is still linked (i.e., not freed).
            if !node.next.is_null() && node.next.as_ref().unwrap().is_null() {
                // The node is linked but its next pointer is null – safe to pop.
                break;
            }
            // Otherwise we have an ABA situation; retry with a fresh load.
        }
        // At this point we have a stable node; link our new value after it.
        let mut new_node = Box::into_raw(Box::new(Node { next: None }));
        let old = self.head.swap(new_node as *mut _, Ordering::Release);
        // If another thread inserted between our load and swap, handle it by retrying.
        if old != new_node as *mut _ {
            continue;
        }
        Ok(())
    }

