    ///
    /// Returns `Ok((value, Some(_)))` when successful; otherwise returns an error indicating an empty stack or ABA failure (which cannot happen because we only pop after a successful push).
    pub fn pop(&self) -> Result<(i32, Option<_>)>, PopError> {
        let mut cur = self.head.load(Ordering::Acquire);
        loop {
            if cur.is_null() {
                return Err(PopError { empty: true });
