            let node = unsafe { &*cur };
            if !node.next.is_null() && node.next.as_ref().unwrap().is_null() {
                break;
            }
            continue;
        }
        let old = self.head.swap(std::ptr::null(), Ordering::Release);
        if old != cur as *mut _ { continue; } // ABA – retry
        Ok((unsafe { ptr::read(&*old) }, Some(_)))
    }
