use std::ptr;

/// A reference‑counted pointer that uses raw pointers for low‑level control.
///
/// * The value is stored as a `NonNull<T>` – a non‑null raw pointer.
/// * Reference counting is performed manually via `dec_ref()` which calls
///   `std::ptr::drop_in_place` on the raw pointer.
/// * The type implements `Deref` so it can be dereferenced like any other
///   smart pointer (e.g., for method calls).
#[derive(Debug)]
pub struct MyRc<T> {
    /// The raw pointer that holds the reference count.
    ptr: NonNull<T>,
}

impl<T> MyRc<T> {
    /// Create an empty (null) reference counted pointer.
    pub fn new() -> Self {
        Self { ptr: NonNull::dangling() }
    }

    /// Create a new reference counted pointer from an existing value.
    pub fn from(value: T) -> Self {
        // SAFETY: we know that `value` lives at least as long as this Rc.
        let ptr = NonNull::new(value).expect("non-null value");
        Self { ptr }
    }
}

impl<T> Deref for MyRc<T> {
    type Target = T;
    fn deref(&self) -> &Self::Target {
        // SAFETY: we have exclusive ownership of the inner value.
        unsafe { &*self.ptr.as_ref() }
    }
}

impl<T> Drop for MyRc<T> {
    fn drop(&mut self) {
        // SAFETY: we own the memory pointed to by `self.ptr`.
        unsafe { dec_ref(self.ptr) };
    }
}

// Helper that decrements the reference count and frees when it reaches zero.
unsafe fn dec_ref(raw: NonNull<u8>) {
    // Convert back to a concrete type; this is safe because we own the memory.
    let value = unsafe { &*raw };
    // Decrement the refcount atomically (the actual implementation would use an atomic).
    // For illustration we just call drop on the inner value; in real code you would use an atomic refcount API.
    drop(value);
}
