        Self { ptr }
    }
}

impl<T> Deref for MyRc<T> {
    type Target = T;
    fn deref(&self) -> &Self::Target {
        // SAFETY: we have exclusive ownership of the inner value.
        unsafe { &*self.ptr.as_ref() }
    }
}

impl<T> Drop for MyRc<T> {
    fn drop(&mut self) {
        // SAFETY: we own the memory pointed to by `self.ptr`.
        unsafe { dec_ref(self.ptr) };
    }
}

// Helper that decrements the reference count and frees when it reaches zero.
unsafe fn dec_ref(raw: NonNull<u8>) {
    // Convert back to a concrete type; this is safe because we own the memory.
    let value = unsafe { &*raw };
    // Decrement the refcount atomically (the actual implementation would use an atomic).
