use std::task::{Context, Poll, Waker};
use std::sync::Arc;
use std::pin::Pin;
use std::future::{Future, FutureExt};
use std::task::{RawWakerVTable, RawWaker};

/// A tiny custom executor that repeatedly polls a single future.
/// It uses the same low‑level primitives described in the docs.
#[derive(Debug)]
struct CustomExecutor {
    /// The future we want to poll.
    fut: Arc<dyn Future<Output = ()> + Send>,
}

impl CustomExecutor {
    /// Create a new executor that will poll *fut* forever.
    pub fn new(fut: Arc<dyn Future<Output = ()> + Send>) -> Self {
        Self { fut }
    }
}

impl Future for CustomExecutor {
    type Output = ();
    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        // 1️⃣ Build a RawWaker from our vtable.
        let raw_waker = Arc::<MyWaker>::new();
        let raw_waker_vtable = RAW_VTABLE;
        let raw_waker = RawWaker::new(
            raw_waker_vtable,
            /* flags */ 0,
            /* data */ ptr::null(),
            ptr::null(),
        );

        // 2️⃣ Wrap it in a RawAsyncBuilder so we can spawn it.
        let builder = tokio::runtimes::Builder::<_, _, _, _>::new()
            .build()
            .unwrap()
            .spawn(CustomExecutor)
            .unwrap()
            .raw()
            .unwrap();

        // 3️⃣ Create a WakeupHandle that will call `wake` on our waker.
        let wakeup = builder.wakeup();

        // 4️⃣ Spawn an async task that repeatedly calls `poll`.
        let task = tokio::spawn(async move {
            while !self.fut.is_terminated() {
                // The wakeup handle will invoke our custom wake function.
                wakeup.poll(&mut *cx);
                // If the future returns Ready, we break out of the loop.
                if self.fut.poll(&mut *cx).is_ready() {
                    break;
                }
                // Otherwise keep polling – this is the core of an async executor.
                continue;
            }
        });

        // 5️⃣ Wait for the task to finish (it will exit when `is_terminated`
        // is called by our custom wake function).
        task.await;
    }
}

