/// A generic iterator wrapper that works with any closure capturing any lifetime.
pub struct ClosureIter<F> {
    // The closure we will invoke; its signature must match FnMut(&mut Self)
    f: F,
}

impl<F> ClosureIter<F>
where
    F: FnMut(&mut Self),
{
    pub fn new(f: F) -> Self {
        Self { f }
    }
}

impl<F> Iterator for ClosureIter<F>
where
    F: FnMut(&mut Self),
{
    type Item = F::Output;
    fn next(&mut self) -> Option<Self::Item> {
        // SAFETY: we know `self` lives at least as long as the returned item because it is stored in the struct.
        let result = self.f(&mut self);
        Some(result)
    }
}
```
In this example, `ClosureIter` can be instantiated with any closure that matches `FnMut(&mut Self)`. The compiler infers the concrete lifetime of each call site, so you can write:
```rust
