use std::sync::{Arc, Mutex, Condvar};
use std::collections::VecDeque;

/// A thread‑safe MPSC channel.
///
/// * `push`  – enqueues an item; blocks if the queue is full.
/// * `pop`   – dequeues an item; blocks if the queue is empty.
/// * `len`   – returns the current number of items in the queue (O(1)).
pub struct MpscChannel<T> {
    /// Shared state protected by a mutex.
    inner: Arc<Mutex<VecDeque<T>>>,
    /// Condition variable used to wake up a blocked consumer.
    cond: Condvar,
}

impl<T> MpscChannel<T> {
    /// Create a new MPSC channel with capacity `capacity`.
    pub fn new(capacity: usize) -> Self {
        let inner = VecDeque::with_capacity(capacity);
        MpscChannel { inner: Arc::new(Mutex::new(inner)), cond: Condvar::new() }
    }

    /// Push an item onto the channel. Blocks until there is space.
    pub fn push(&self, item: T) {
        // Acquire exclusive access to the inner vector.
        let mut guard = self.inner.lock().unwrap();
        // Wait until there is room for another element.
        self.cond.wait(&mut guard).expect("MPSC channel full");
        // Insert at the tail (back).
        guard.push_back(item);
    }

    /// Pop an item from the channel. Blocks until there is data.
    pub fn pop(&self) -> Option<T> {
        let mut guard = self.inner.lock().unwrap();
        // Wait until there is at least one element available.
        self.cond.wait(&mut guard).expect("MPSC channel empty");
        // Remove from the front (front).
        guard.pop_front()
    }

    /// Returns true if there are any items waiting in the queue.
    pub fn is_empty(&self) -> bool {
        let mut guard = self.inner.lock().unwrap();
        guard.is_empty()
    }

    /// Returns true if there are any items waiting in the queue and can be consumed immediately without blocking.
    pub fn try_peek(&self) -> Option<T> {
        let mut guard = self.inner.lock().unwrap();
        if !guard.is_empty() { Some(*guard.front()) } else { None }
    }
}
```
### Explanation of Design Choices
1. **`Arc<Mutex<VecDeque>>`** – Allows multiple threads to share ownership of both the vector and its lock without copying heavyweight structures on each clone.
2. **`VecDeque`** – Provides O(1) push/pop at both ends, which matches the typical MPSC pattern where producers append and consumers remove from opposite ends.
3. **`Condvar`** – Implements classic condition‑variable semantics (`wait`/`notify`) required by many Rust concurrency patterns (including `mpsc!`, `oneshot!`, etc.).
4. **Blocking Semantics** – Both `push` and `pop` block until space or data becomes available, guaranteeing that no data race occurs because all accesses are serialized by the mutex and wake‑ups are coordinated via `Condvar`.
5. **Zero‑Copy Guarantees** – The channel does not move or clone elements; it merely stores references (`&T`) inside `VecDeque`. This respects Rust’s safety guarantees while still providing thread‑safe sharing.

