/// A thread‑safe MPSC channel.
///
/// * `push(&mut self, item: T)` – enqueues an item; blocks if the queue is full.
/// * `pop(&mut self) -> Option<T>` – dequeues an item; blocks if the queue is empty.
/// * `is_empty(&self) -> bool` – returns true if there are no pending items.
///
/// The channel uses an [`Arc`] to share ownership across threads and a
/// [`Mutex`] to protect the internal vector. A [`Condvar`] synchronises
/// producers and consumers so that they block until space or data becomes
/// available.
pub struct MpscChannel<T> {
    /// Shared state protected by a mutex.
    inner: Arc<Mutex<VecDeque<T>>>,
    /// Condition variable used to wake up a blocked consumer.
    cond: Condvar,
}

impl<T> MpscChannel<T> {
    /// Create a new MPSC channel with capacity `capacity`.
    pub fn new(capacity: usize) -> Self {
        let inner = VecDeque::with_capacity(capacity);
        MpscChannel { inner: Arc::new(Mutex::new(inner)), cond: Condvar::new() }
    }

    /// Push an item onto the channel. Blocks until there is space.
    pub fn push(&mut self, item: T) -> Result<(), &'static str> {
        // Acquire exclusive access to the inner vector.
        let mut guard = self.inner.lock().unwrap();
        // Wait until there is room for another element.
        self.cond.wait(&mut guard).map_err(|_| "queue full")?; // propagate error instead of panic
        // Insert at the tail (back).
        guard.push_back(item);
        Ok(())
    }

    /// Pop an item from the channel. Blocks until there is data.
    pub fn pop(&mut self) -> Result<Option<T>, &'static str> {
        let mut guard = self.inner.lock().unwrap();
        // Wait until there is at least one element available.
        self.cond.wait(&mut guard).map_err(|_| "queue empty")?; // propagate error instead of panic
        // Remove from the front (front).
        guard.pop_front()
    }
}
```
