    // We keep only the current element and the previous one.
    prev: Option<&'a T>,
}

impl<'a, T> SlidingWindow<'a, T> {
    /// Create a new iterator that starts at index `start`.
    pub fn new(slice: &'a [T], start: usize) -> Self {
        Self { slice, prev: None }
            .advance(start)
            .expect("start index out of bounds")
    }
}

impl<'a, T> Iterator for SlidingWindow<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<Self::Item> {
        // If we have reached the end of the slice or there is no previous element,
        // advance to the next position.
        if self.prev.is_none() || self.prev == &self.slice[self.slice.len()] {
            self.advance();
            return None;
        }
        // Yield a reference to the current element.
        Some(&self.prev)
    }
