#[derive(Debug)]
pub struct SlidingWindow<'a, T> {
    /// Underlying slice we are iterating over.
    slice: &'a [T],
    /// Index of the element that will become `curr`.
    curr_idx: usize,
    /// Index of the element that will become `prev`.
    prev_idx: usize,
}

impl<'a, T> SlidingWindow<'a, T> {
    /// Create an iterator starting at index `start`.
    ///
    /// If `start` is greater than or equal to `slice.len()`, we immediately
