        unsafe { *node.prev.get_mut().unwrap() = Some(*node); }
        unsafe { *node.next.get_mut().unwrap() = Some(*node); }

        // Ensure we have at least one element after insertion.
        if self.head == None && self.tail == None {
            // Cache was empty; set both pointers to this newly inserted node.
            *head.get_mut().unwrap() = Some(*node);
            *tail.get_mut().unwrap() = Some(*node);
            return;
