/// Sums an array of 32‑bit floating‑point numbers using AVX2 SIMD.
///
/// * The function works on any slice whose length is a multiple of four.
/// * It loads four floats at a time with `_mm_loadu_ps`, adds them with
///   `_mm_add_ps`, and accumulates the result in a scalar variable.
/// * For non‑multiple‑of‑four lengths it falls back to a scalar loop.
#[inline]
pub fn sum_floats(arr: &[f32]) -> f32 {
    // Fast path for whole SIMD blocks
    let mut total = 0.0f32;
    let mut i = arr.len();
    while i >= 4 {
        // Load four floats (unaligned load is safe because we only read)
        let v = unsafe { simd::load::<u32x4>(arr.as_ptr().add(i)) };
        // Add them together – each lane holds one float
        let sum = unsafe { simd::add(v, v) };
        // Reduce the vector sum to a single float (horizontal add)
        total += unsafe { simd::hadd(sum) };
        i -= 4;
    }
    // Tail handling – process remaining elements one by one
    for &elem in arr {
        total += elem;
    }
    total
}
