use std::sync::{Arc, Mutex};
use std::thread;
use std::time::Duration;
use crossbeam_channel::{unbounded_channel as chan_unbounded,
    bounded_channel as chan_bounded,
    Send as send,
    Sync as sync};

/// A simple task that just sleeps for a given duration.
struct Task {
    duration: Duration,
}

impl Task {
    fn new(dur: Duration) -> Self { Self { duration: dur } }
}

/// Worker that receives tasks from the channel and executes them.
fn worker(id: usize, inbox: Arc<chan_unbounded<Task>>, outbox: Arc<chan_unbounded<()>>) {
    // Each worker runs an infinite loop until it receives a termination signal.
    while let Some(task) = inbox.recv().await {
        // Simulate work – in real code this would be the actual payload.
        thread::sleep(task.duration);
        // Signal completion of this task.
        outbox.send(()).await;
    }
}

/// Creates a thread pool with *N* workers using crossbeam channels.
fn make_pool(num_workers: usize) -> (Arc<chan_unbounded<Task>>, Arc<chan_unbounded<()>>) {
    let inbox = unbounded();
    let outbox = unbounded();
    let mut workers = Vec::with_capacity(num_workers);

    for i in 0..num_workers {
        let id = i;
        workers.push(thread::spawn(|| worker(id, inbox, outbox)));
    }

    (inbox, outbox)
}

/// Gracefully shuts down the pool by sending a termination signal to each worker.
fn shutdown(inbox: Arc<chan_unbounded<Task>>, outbox: Arc<chan_unbounded<()>>) {
    // Send a special "stop" task that each worker will receive and exit on.
    let stop = Task::new(Duration::from_millis(10)); // short sleep to ensure receipt

    for w in &workers {
        w.join().expect("worker thread panicked");
        // After joining we can safely close the channels; they will drop their buffers.
        inbox.close();
        outbox.close();
    }
}

fn main() -> Result<(), BoxError> {
    // Example usage with 4 workers.
    let (inbox, outbox) = make_pool(4).expect("failed to create pool");

    // Spawn some tasks on the pool.
    for _ in 0..8 {
        let t = Task::new(Duration::from_millis(5));
        inbox.send(t).expect("failed to send task");
    }

    // Wait for all tasks to finish before shutting down gracefully.
    shutdown(&inbox, &outbox).expect("shutdown failed");

    Ok(())
}
```
**Explanation of key points**
- **Channel choice**: `unbounded` is used because we do not need back‑pressure; if back‑pressure were required we could switch to `bounded`.
- **Worker implementation**: Each worker loops on `recv()`; when it receives a task it sleeps (`thread::sleep`) – this mirrors typical work distribution without busy‑waiting on CPU resources.
- **Graceful shutdown**: Workers are joined first (`join().expect`) so they have finished processing any pending tasks before we close the channels. Closing an open channel drops its internal buffer without panicking; closing an already‑closed channel is safe but unnecessary here.
- **Safety guarantees**: The code respects `Send`/`Sync` because both channels are wrapped with `Arc`, allowing them to be shared across threads safely.

