let (tx_mailbox, rx_mailbox): (Arc<mpsc::Sender<Message>>, Arc<mpsc::Receiver<Message>>) =
    mpsc::channel();

// 3️⃣ Actor implementation – receives messages from the mailbox and replies.
async fn actor(id: u32) -> Result<(), Box<dyn std::error::Error>> {
    // Wait for a message; if none arrives within 500ms we timeout.
    let msg = rx_mailbox.recv().await.ok_or("no message")?;
    println!("Actor {} received: {}", id, msg.payload);

    // Simulate work – could be any async computation.
    tokio::time::sleep(Duration::from_millis(10)).await;

    // Send a reply back to the original sender.
    tx_mailbox.send(msg).await?;
    Ok(())
}

// 4️⃣ Spawn two actors on separate threads (Tokio runtime).
#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let tx = tx_mailbox.clone();
    let rx = rx_mailbox.clone();

    // Launch first actor on thread #1.
    tokio::spawn(actor(1));

    // Launch second actor on thread #2 – it will wait for the first to finish.
    tokio::spawn(actor(2));

    // Main thread waits for both actors to finish.
