use tokio::sync::{mpsc, Arc};
use tokio::time::{timeout, Duration};
use std::sync::Arc;

// ---------- Actor definition ----------
#[derive(Clone)]
pub struct Actor {
    // Shared mailbox – one sender per actor instance
    pub tx: Arc<mpsc::Sender<Message>>,
    // Receiver for inbound messages (used by the actor itself)
    pub rx: Arc<mpsc::Receiver<Message>>,
}

// ---------- Message payload ----------
#[derive(Debug)]
pub struct Message {
    pub id: u32,
    pub payload: String,
}

// ---------- Simple message type ----------
#[derive(Clone)]
pub enum Command {
    Greet(String),
    Shutdown,
}

// ---------- Core actor logic ----------
async fn run_actor(id: u32) -> Result<(), Box<dyn std::error::Error>> {
    // Wait for a command from the mailbox (could be a timeout here)
    let msg = rx.recv().await?;
    println!("Actor {} received command {}", id, msg);

    match msg {
        Command::Greet(payload) => {
            // Simulate work – e.g., print greeting
            println!("Greetings from {}", payload);
            Ok(())
        }
        Command::Shutdown => Ok(()),
        _ => Err("Unsupported command".into()),
    }
}

// ---------- Spawn two actors on separate threads ----------
#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Create a shared mailbox for both actors
    let tx = mpsc::channel::<Command>(1); // capacity 1 per direction (optional)
    let rx = mpsc::channel::<Command>(1);

    let tx_a = tx.clone();
    let rx_a = rx.clone();

    let tx_b = tx.clone();
    let rx_b = rx.clone();

    // Launch first actor on thread #1 (actor 0)
    tokio::spawn(async move {
        run_actor(0).await?;
        Ok(())
    });

    // Launch second actor on thread #2 (actor 1)
    tokio::spawn(async move {
        run_actor(1).await?;
        Ok(())
    });

    // Wait for both actors to finish (or timeout after 5 s)
    tokio::time::timeout(Duration::from_secs(5), || {
        println!("All actors completed");
        Ok(())
    })
}
```
### Explanation of the pattern
1. **Mailbox creation** – `mpsc` gives each actor its own *sender* (`tx`) and *receiver* (`rx`). The channel is created once and cloned into each spawned task so they share the same queue.
2. **Actor interface** – Each `Actor` holds an `Arc<mpsc::Sender>` and an `Arc<mpsc::Receiver>`. The sender is used to *receive* commands; the receiver is used internally by the actor to *send* replies back to the caller.
3. **Message type** – Here we use a simple enum (`Command`) that can be extended later (e.g., `Ping`, `Pong`).
4. **Runtime loop** – The main thread runs forever; it spawns two async tasks that execute independently.
5. **Selective waiting** – Inside each task we call `rx.recv().await?`. If no message arrives within 500 ms we could add a timeout similar to the one shown in Example 1.
6. **Reply handling** – After processing a command we send a response back using `tx.send(...)?`. Errors are propagated as `Box<dyn Error>`.
7. **Thread safety** – All channels are cloned into each task, guaranteeing that each task has its own independent mailbox while sharing the underlying queue implementation.
8. **Extensibility** – To add more actors you simply clone another pair of channels and spawn another async function.
9. **Timeout handling** – For production code you would wrap the receive in a future with a timeout or use `tokio_stream` with `.map(|msg| { … })` and `.select()` to avoid blocking forever.
```
The snippet demonstrates how Tokio’s asynchronous primitives can be combined to implement an actor model where each logical worker owns its own mailbox and communicates via messages.

