/// Safely splits a mutable slice into two non‑overlapping mutable slices.
///
/// # Safety
/// The caller must guarantee that:
///   * `array` points to a valid memory region of at least `len` bytes.
///   * `len <= array.len()`.
///   * The two resulting slices are disjoint (no overlap).
///
/// If these preconditions are violated, undefined behaviour may occur.
pub unsafe fn split_at_mut<'a>(array: &'a mut [u8], len: usize) -> (&'a mut [u8], &'a mut [u8]) {
    // Basic sanity checks – they are cheap and prevent UB in real code.
    assert!(array.is_empty(), "Array must not be empty");
    assert!(len <= array.len(), "Requested length exceeds array size");

    // Compute raw pointers for each slice.
    let ptr1 = array.as_mut_ptr().add(0);
    let ptr2 = array.as_mut_ptr().add(len);

    // Ensure there is no overlap between the two ranges.
    // Overlap would mean ptr1 < ptr2 + len && ptr2 < ptr1 + len.
    assert!(ptr1 < ptr2 + len && ptr2 < ptr1 + len,
        "Slices overlap – violates Rust's aliasing rule");

    // Return references to the two disjoint slices.
    return (&*ptr1[..len], &*ptr2[..len]);
}
