// StoreFunc is a function that retrieves data from an external source.
type StoreFunc func(ctx context.Context) (interface{}, error)

// CacheEntry holds the result of a successful lookup.
type CacheEntry struct {
    Value interface{}
    Err   error
}

// Singleflight provides request coalescing for concurrent calls.
type Singleflight struct {
    mu sync.Mutex // protects the map of pending requests
    mu2 sync.Mutex // protects the map of completed requests (optional)
    mu3 sync.Mutex // protects the final result storage (optional)
}

func New(store StoreFunc) *Cache {
    return &Cache{store: store}
}

// Get performs a cached lookup with singleflight semantics.
func (c *Cache) Get(ctx context.Context, key string) (interface{}, error) {
    // First attempt – try to get from cache without any synchronization.
    if v, err := c.cacheLookup(ctx, key); err == nil {
        return v, nil
    }

    // If we got here without an error but also without a value,
    // we need to perform the expensive operation exactly once.
    if err != nil && errors.Is(err, ErrNotFound) {
        // Record that we are now performing the operation.
        c.sfMu2.Lock()
        defer c.sfMu2.Unlock()
        c.sfMu3.Lock()
        defer c.sfMu3.Unlock()
        // Perform the operation outside any lock to avoid deadlock.
        value, err := c.store(ctx)
        if err == nil {
            c.cacheStore(key, value)
            return value, nil
        }
        // Propagate any error from the store operation.
        return nil, err
    }

    // If we already have an error or a cached value with an error,
    // forward that directly – no need to retry.
    return v.(interface{}), fmtErr(v.(error))
}

// cacheLookup performs an unsynchronized lookup first.
func (c *Cache) cacheLookup(ctx context.Context, key string) (interface{}, error) {
    if v := c._cache[key]; v != nil {
        return v.(interface{}), nil
    }
    return nil, ErrNotFound
}

// cacheStore stores a successful result in the cache map.
func (c *Cache) cacheStore(key string, value interface{}) {
    c._cache[key] = value
}
