// Reader implements io.Reader by reading from an underlying source,
// decrypting each AES-CTR block on‑the-fly.
type Reader struct {
    r      io.Reader // underlying source (e.g., os.File)
    key    []byte   // 16‑byte AES key (must be 16 bytes)
    iv     []byte   // 16‑byte IV (nonce) – must be unique per encryption
    ctrLen int      // length of the counter block (usually 8 for AES‑CTR)
}

// NewReader creates a Reader given an underlying reader, key and IV.
func NewReader(r io.Reader, key []byte, iv []byte) *Reader {
    return &Reader{r: r, key: key, iv: iv}
}

// Read implements io.Reader.
func (r *Reader) Read(p []byte) (int, error) {
    // Buffer to hold partial blocks until we have enough for one full block.
    var buf [16]byte // enough for one AES block (128 bits)
    n := len(p)

    for {
        if n == 0 {
            return 0, nil // nothing to read yet
        }
        if len(buf) < r.ctrLen {
            // Fill buf with more plaintext from the underlying reader.
            nRead, err := r.Read(buf[:])
            if err != nil && err != io.EOF {
                return 0, err
            }
            if nRead > len(buf) {
                nRead = len(buf)
            }
            if err == io.EOF && len(buf) == 0 {
                return 0, io.EOF
            }
            continue // try again after filling buf
        }
        // At this point we have at least one full block in buf.
        copy(p[:], buf[:r.ctrLen])
        p = p[r.ctrLen:]
        n -= r.ctrLen
        if len(p) >= r.ctrLen {
            continue // more data available for next iteration
        }
        // Not enough data yet – wait for more input or EOF.
        return n, nil
    }
}
```
