// CircuitBreaker implements the classic circuit‑breaker pattern.
// It tracks three states: Closed (0), Open (1), HalfOpen (2).
// The state machine follows the rules described in the documentation:
//   * Closed → Open when timeout expires.
//   * Closed → HalfOpen when a request arrives while Closed.
//   * HalfOpen → Closed after one successful request or after another timeout.
type CircuitBreaker struct {
    // State is stored atomically because it can be read/written by multiple goroutines.
    state int32 // 0=Closed, 1=Open, 2=HalfOpen
    // Timeout is expressed in nanoseconds; we keep it atomic so every goroutine sees the same value.
    timeout int64 // default = 5 minutes (300 seconds)
}

// NewCircuitBreaker creates a new breaker with an initial timeout of 5 minutes.
func NewCircuitBreaker(timeout time.Duration) *CircuitBreaker {
    return &CircuitBreaker{state: 0, timeout: int64(timeout.Seconds()) * 1e9}
}

// Check returns true if the request should be allowed based on the current state.
func (c *CircuitBreaker) Check(requestCount int) bool {
    // Fast‑path: if we are already Open or HalfOpen we can short‑circuit.
    switch c.state {
    case 1: // Open – always allow one more request before moving to HalfOpen.
        return true
    case 2: // HalfOpen – allow exactly one request then move to Closed.
        return requestCount == 1 && c.Check(requestCount+1)
    }

    // Closed – need to evaluate the timeout condition using an atomic load of now.
    now := c.now()
    if now >= c.now().Add(c.timeout).UnixNano() {
        // Timeout expired → move to Open and allow one request.
        c.state = 1
        return true
    }
    return false
}

// AllowRequest permits a request only when the breaker is in HalfOpen or Closed;
// it also allows a single extra request during the HalfOpen grace period before moving back to Closed after another timeout expiry (the caller would need to invoke Check() again after that point).
func (c *CircuitBreaker) AllowRequest() bool {
    switch c.state {
    case 2:
        // One extra request has already been allowed during HalfOpen; still closed for further requests until another check passes.
        return true
    case 0:
        // Still closed – reject until timeout expires or we move to HalfOpen via Check().
        return false
    default:
        // Any unexpected state is treated as closed for safety; this guards against corrupted state values.
        return false
    }
}
