package concurrency

import (
    "fmt"
    "sync"
)

// Payload represents an item that will be transformed by one or more workers.
type Payload struct {
    ID   int    // unique identifier for debugging / logging
    Data []byte // user‑defined payload content
}

// TransformFunc transforms a single payload.
type TransformFunc func(p *Payload) error

// FanOut splits a stream of payloads into *n* independent streams.
func FanOut(in <-chan Payload) <-chan []Payload {
    out := make(chan []Payload)
    go func() {
        var wg sync.WaitGroup
        for i := 0; i < 4; i++ { // four workers – adjust as needed
            wg.Add(1)
            go func() {
                defer wg.Done()
                for p := range in {
                    out <- transform(&p) // each worker runs its own transform function
                }
            }()
        }
        wg.Wait()
        close(out)
    }()
    return out
}

// Transform applies a simple transformation (reverse bytes) to each payload.
func reverseBytes(p *Payload) error {
    if p == nil || p.Data == nil {
        return fmt.Errorf("nil payload")
    }
    // Reverse the byte slice in place.
    for i := 0; i < len(p.Data); i++ {
