        keyToVal[k] = valPtr
        personAddrField = personAddrField.FieldByName("Address")
        personAddrField = personAddrField.(reflect.Value).SetMapIndex(keyToVal[k], 0)
        fmt.Printf("Setting address %s -> %s\n", k, vStr)
