package main

import (
    "context"
    "fmt"
    "log"
    "os"
    "time"

    "golang.org/x/sync/errgroup"
)

// worker performs a simple task and returns an error if something goes wrong.
func worker(id int, ctx context.Context, wg *errgroup.Group) {
    defer wg.Done()
    // Simulate work with a short delay.
    time.Sleep(10 * time.Millisecond)
    // Return an error if we reach this point – in real code this could be I/O or validation.
    if id%2 == 0 {
        return fmt.Errorf("worker %d failed", id)
    }
}

func main() {
    const workers = 5
    var wg errgroup.Group

    // Launch all workers concurrently.
    for i := 0; i < workers; i++ {
        wg.Go(func() error {
            return worker(i, context.Background(), &wg)
        })
    }

    // Wait for all workers to finish.
    if err := wg.Wait(); err != nil {
        log.Fatalf("one of the workers failed: %v", err)
        return
    }

    fmt.Println("All workers completed successfully.")
}
```
**Explanation of cancellation behavior**
- Each worker calls `wg.Go`, which schedules the function on its own goroutine.
- If any worker returns an error, `errgroup` marks the group as done and propagates that error to `wg.Wait`.
- Because all workers were launched before `Wait`, they are already running when the first error occurs.
- The Go runtime automatically cancels any pending tasks started by those workers once `wg` reports completion with an error.
- Consequently, no additional cleanup code is required; the program exits after logging the failure.

