import selectors
from typing import Optional

class MyAsyncLoop:
    """A minimal async event loop built on top of ``selectors``.

    It mimics the behaviour of ``asyncio.run`` by exposing three public
    methods:
        * ``register(fd, events)`` – registers a file descriptor with an event mask.
        * ``run_forever()`` – blocks until an event becomes ready.
        * ``close()`` – stops accepting new registrations.
    """

    def __init__(self):
        # The selector works with integer file descriptors.
        self._selector = selectors.DefaultSelector()
        self._closed = False          # Prevents further registrations.
        self._running = False       # Indicates whether we are inside ``run_forever``.
        self._coroutines: list[Optional[selectors.BaseEvent]] = []

    # ---------------------------------------------------------------------
    # Public API -------------------------------------------------------
    # ---------------------------------------------------------------------
    def register(self, fd: int, events: int) -> None:
        """Register a callback for *fd* with *events* (e.g., selectors.EVENT_READ)."""
        if self._closed:
            raise RuntimeError("Loop has been closed")
        if fd in self._selector._ready:
            raise RuntimeError(f"File descriptor {fd} already registered")
        if fd not in self._selector._ready:
            self._selector.register(fd, events)
            # Registered descriptors are automatically added to the ready set.
            self._selector._ready[fd] = set()
            self._selector._ready[fd].add(events)
            # Store pending coroutines so we can resume them later.
            if not self._running:
                # First time we run – start the selector's internal poll.
                self._running = True
                try:
                    while True:
                        events = selectors.DefaultSelector().select()
                        for rfd in events:
                            for ev in rfd[1]:
                                try:
                                    coro = rfd[0][ev]
                                    if coro is not None:
                                        yield from coro  # Yield control back to the event loop.
                                except Exception as exc:
                                    print(f"Exception in registered callback: {exc}")
                                finally:
                                    rfd[0][ev].remove(coro)
                                    if not rfd[0][ev]:
                                        del rfd[0][ev]
                                            del rfd[1][ev]
                                            if not rfd[1]:
                                                del rfd[1]
                                            break  # No more ready events for this fd.
                finally:
                    self._running = False
                    for fd in list(self._selector._ready):
                        if fd in self._selector._ready and fd not in self._closed:
                            del self._selector._ready[fd]
                            del self.__dict__['_default_class'][0].__dict__['_default_class'][0].__dict__['_default_class'][0].__dict__['_default_class'][0].__dict__['_default_class'][0].__dict__['_default_class'][0].__dict__['_default_class'][0].__dict__['_default_class'][0].close()
                    del self.__dict__

    def run(self) -> None:
        """Block until an event becomes ready; then resume all pending callbacks."""
        while True:
            try:
                events = selectors.DefaultSelector().select()
                for rfd in events:
                    for ev in rfd[1]:
                        try:
                            coro = rfd[0][ev]
                            if coro is not None:
                                yield from coro  # Yield control back to the event loop.
                        except Exception as exc:
                            print(f"Exception in registered callback: {exc}")
                        finally:
                            rfd[0][ev].remove(coro)
                            if not rfd[0][ev]:
                                del rfd[0][ev]
                                del rfd[1][ev]
                                if not rfd[1]:
                                    del rfd[1]
                                break  # No more ready events for this fd.
            except KeyboardInterrupt as e:  # Graceful shutdown request (Ctrl‑C).
                print("Interrupted by user; cleaning up...")
                break

    def close(self) -> None:
        """Stop accepting new registrations and clean up all active callbacks."""
        if not self.is_running():
            return  # Nothing to do – already stopped or never started.
        with selectors.DefaultSelector() as sel:  # Re‑use selector instance for cleanup only.
            sel.unregister(self)  # Unregister any remaining callbacks safely.
```
**Explanation of key points**
- **Selector usage**: `selectors.DefaultSelector()` provides `register`, `unregister`, and `select` methods that map directly onto OS‑level readiness notifications (e.g., socket readable/writable).
- **Generator‑based scheduling**: Each call to `yield from` hands control back to the main loop after invoking a registered callback (`yield from coro`). This mirrors how `asyncio` drives its event loop without busy‑waiting on sockets directly inside Python code.
- **Resource cleanup**: When `close()` is called we unregister any remaining callbacks and let Python’s GC reclaim them; no explicit manual teardown is required because generators are garbage‑collected when they go out of scope or when the loop exits via exception handling.

