# A simple runtime check for missing docstrings – raises ``RuntimeError`` if violated.
def _check_docstring(cls):
    for name, method in inspect.getmembers(cls):
        if callable(method) and not getattr(method, "__doc__", None):
            raise RuntimeError(f"Method {name!r} on {cls.__name__} lacks a docstring")

# A simple runtime check for missing type annotations – raises ``RuntimeError`` if violated.
def _check_annotations(cls):
    for name, method in inspect.getmembers(cls):
        if callable(method) and not getattr(method, "__annotations__", None):
            raise RuntimeError(
                f"Method {name!r} on {cls.__name__} does not have a type annotation"
            )

class EnforcedSubclassMeta(type):
    """Metaclass that validates subclasses at definition time."""

    def __new__(mcs, clsname, bases, namespace):
        # Step 1: Validate existing members (including inherited ones)
        _check_docstring(namespace)
        _check_annotations(namespace)

        # Step 2: Call the original ``type.__new__`` to create the class object
        new_cls = super().__new__(mcs, clsname, bases, namespace)
        return new_cls
